const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const fireLocation = ee.Geometry.Point([-116.3, 31.5]); // El Escondido area
  const targetPoint = ee.Geometry.Point([-118.2, 31.5]); // ~100km west (1° longitude ≈ 88km at this latitude)
  const targetBuffer = targetPoint.buffer(10000); // 10km buffer to capture plume

  const date = '2025-01-23';
  const timeRange = ee.Date(date).advance(5, 'hour').getRange('hour'); // ±2.5 hours around 1:44 PM

  // 2. Data Acquisition - Use VIIRS for fire/smoke detection
  const viirs = ee.ImageCollection('NOAA/VIIRS/001/VNP09GA')
    .filterDate(timeRange.start(), timeRange.end())
    .filterBounds(fireLocation);

  // Check for data availability
  const viirsSize = viirs.size().getInfo();
  console.log(`VIIRS Images: ${viirsSize}`);

  if (viirsSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Processing - Create smoke mask using SWIR and visible bands
  const addSmokeMask = function(img) {
    const swir = img.select('I3');  // SWIR band for smoke detection
    const visible = img.select('I1'); // Red band
    const smokeMask = swir.lt(0.15).and(visible.gt(0.1)); // Empirical thresholds
    return img.addBands(smokeMask.rename('smoke'));
  };

  const viirsSmoke = viirs.map(addSmokeMask).median();

  // 4. Check valid pixels in target area
  const targetSmoke = viirsSmoke.select('smoke');
  const smokeStats = targetSmoke.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: targetBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const smokeCount = smokeStats.get('smoke').getInfo();
  console.log(`Smoke pixels in target: ${smokeCount}`);

  if (smokeCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate smoke coverage percentage in target area
  const smokeArea = targetSmoke.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: targetBuffer,
    scale: 1000,
    maxPixels: 1e9
  });

  const smokeCoverage = smokeArea.get('smoke').getInfo();
  console.log(`Smoke coverage: ${(smokeCoverage * 100).toFixed(1)}%`);

  // 6. Validation & Final Answer
  // Smoke coverage > 10% indicates significant plume extension
  if (smokeCoverage === null || smokeCoverage === undefined || smokeCoverage < 0 || smokeCoverage > 1) {
    console.log("<answer>C3</answer>");
  } else if (smokeCoverage > 0.1) { // 10% coverage threshold
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
